head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil00052";
scwin.upd_attachFile = null;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
        scwin.upd_attachFile = (typeof __krxFileControl === 'function') ? __krxFileControl('upd_attachFile') : ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document).querySelector('[id="upd_attachFile"]');
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldfil00052.onpageload' });
    }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_ElwExcelUpload_onclick
 * @description 「Excel 업로드」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_ElwExcelUpload_onclick = async function(e){
    try {
        await scwin.elwExcelUpload()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil00052.btn_ElwExcelUpload_onclick' }); }
};

/**
 * @method
 * @name btn_closePop_onclick
 * @description 「닫기」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_closePop_onclick = async function(e){
    try {
        await scwin.close_pop()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil00052.btn_closePop_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_ElwExcelUpload
 * @description Elw Excel Upload 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_ElwExcelUpload = async function () {
    const sbmOptions = {
        id: "tx_fn_ElwExcelUpload",
        method: "post",
        action: "/submission/disclosureExl.do?method=excelUpload",
        ref: "dma_ElwExcelUploadReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name elwExcelUpload
 * @description elw Excel Upload 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.elwExcelUpload = async function () {
    const form = (document.disclosureFrm || { elements: [] });
    if ($c.util.getComponent('upd_attachFile').getValue() == null || ($c.util.getComponent('upd_attachFile').getValue() == null ? '' : String($c.util.getComponent('upd_attachFile').getValue())) === '') {
        return;
    } else {
        if (!scwin.checkFileType($c.util.getComponent('upd_attachFile').getValue())) {
            await $c.win.alert("엑셀 파일만(xls) 업로드 가능합니다.");
            $("#upd_attachFile").replaceWith($("#upd_attachFile").clone(true));
            return;
        }
    }
    if (await $c.win.confirm("업로드 하시겠습니까?")) {
        prgIfm.setStyle("display", "");
        $("#prgIfm").attr("src", "/common/progress_blank_pop.jsp");
        $('.btn_w_gra').bind('click', false);
        form.action = "/submission/disclosureExl.do?method=excelUpload";
        await scwin.tx_fn_ElwExcelUpload();
        (($c.util.getComponent('upd_attachFile')) && ($c.util.getComponent('upd_attachFile')).setDisabled ? ($c.util.getComponent('upd_attachFile')).setDisabled(('disabled') === 'disabled' || ('disabled') === 'readonly' || ('disabled') === 'checked' ? true : ('disabled')) : void 0);
    }
};

/**
 * @method
 * @name checkFileType
 * @description check File Type 처리
 * @param {*} filePath filePath
 * @returns {void}
 * @hidden N
 */
scwin.checkFileType = function (filePath) {
    if (filePath == null || filePath === "") {
        return false;
    }
    const tfp = filePath.toLowerCase();
    if (tfp.indexOf(".xls") < 0 || tfp.substr(tfp.length - 4, 4) !== ".xls") {
        return false;
    }
    return true;
};

/**
 * @method
 * @name close_pop
 * @description close pop 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.close_pop = async function () {
    if ($c.util.getComponent('upd_attachFile').getValue().length > 0) {
        if (await $c.win.confirm("종료 하시겠습니까?")) {
            $c.win.closePopup();
        } else {
            return;
        }
    }
    $c.win.closePopup();
};
